export interface CopilotCodeGuidelineReviewCommentProps {
  threadSubject: {diffLines?: StaticDiffLine[]} & {path: string; isResolved: boolean; pullRequestId: string; id: string}
  thread: Thread
}

export function CopilotCodeGuidelineReviewComment({threadSubject}: CopilotCodeGuidelineReviewCommentProps) {
  return (
    <>
      <div className="border borderColor-muted overflox-x-auto">
        <StaticUnifiedDiffPreview tabSize={4} diffLines={threadSubject.diffLines} />
      </div>
    </>
  )
}

try{ CopilotCodeGuidelineReviewComment.displayName ||= 'CopilotCodeGuidelineReviewComment' } catch {}